using namespace System.Net

# $sub and $DID are injected by CloudLabs.
#
# Two things measured on a live run, 6 Oct 2026, that this script previously got wrong:
#   1. The policy GUID was held in $pid. $PID is a Constant, AllScope automatic variable, so the
#      assignment threw "Cannot overwrite variable PID because it is read-only or constant" and the
#      challenge failed on every run before it ever looked at the standard. Renamed to $policyId.
#   2. A custom standard created through the portal has properties.assessments = [] ALWAYS. The
#      selected recommendation lives in the Azure Policy initiative named by
#      properties.policySetDefinitionId. The check now follows that initiative, and keeps the
#      assessments path as a fallback for standards created by other means.
$rg=(Get-AzResource -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'asclab*' } | Select-Object -First 1).ResourceGroupName; if(-not $rg){ throw 'Could not locate the lab resource group: no resource named asclab* found in the subscription.' };$count=0;$found=$false;$lastReason='No attempt completed.'
function P($o,$n){if($null -eq $o){return $null};$p=$o.PSObject.Properties[$n];if($null -eq $p){return $null};$p.Value}
function Reply($s,$m){if($s -eq 'Succeeded'){$body=@{Status = "Succeeded";Message = $m}|ConvertTo-Json -Depth 12 -Compress}else{$body=@{Status = "Failed";Message = $m}|ConvertTo-Json -Depth 12 -Compress};Push-OutputBinding -Name Response -Value ([HttpResponseContext]@{StatusCode=[HttpStatusCode]::OK;Body=$body}) -Clobber}
do{$count++;try{Set-AzContext -Subscription $sub -ErrorAction Stop|Out-Null;$storage=@(Get-AzStorageAccount -ResourceGroupName $rg -ErrorAction Stop|Where-Object{$_.StorageAccountName -like 'asclabsa*'});if($storage.Count-ne 1){throw "Expected exactly one asclabsa* storage account; found $($storage.Count)."};$sa=$storage[0];if([string](P $sa 'PublicNetworkAccess')-notin @('Disabled','disabled')){throw "Storage '$($sa.StorageAccountName)' public network access is not Disabled."};if([string](P $sa 'MinimumTlsVersion')-ne 'TLS1_2'){throw "Storage '$($sa.StorageAccountName)' MinimumTlsVersion is not TLS1_2."};if((P $sa 'EnableHttpsTrafficOnly')-ne $true){throw "Storage '$($sa.StorageAccountName)' HTTPS-only access is not enabled."};$sql=@(Get-AzSqlServer -ResourceGroupName $rg -ErrorAction Stop|Where-Object{$_.ServerName -like 'asclab-sql*'});if($sql.Count-ne 1){throw "Expected exactly one asclab-sql* SQL server; found $($sql.Count)."};$server=$sql[0];if([string](P $server 'PublicNetworkAccess')-notin @('Disabled','disabled')){throw "SQL server '$($server.ServerName)' public network access is not Disabled."};$wide=@(Get-AzSqlServerFirewallRule -ResourceGroupName $rg -ServerName $server.ServerName -ErrorAction SilentlyContinue|Where-Object{$_.StartIpAddress-eq '0.0.0.0' -and $_.EndIpAddress-in @('0.0.0.0','255.255.255.255')});if($wide.Count){throw "SQL server '$($server.ServerName)' still has internet-wide firewall rule '$($wide[0].FirewallRuleName)'. Remove it under Networking > Selected networks before switching public network access to Disable - the portal hides the firewall section once Disable is selected."};$vault=@(Get-AzKeyVault -ResourceGroupName $rg -ErrorAction Stop|Where-Object{$_.VaultName -like 'asclab-kv*'});if($vault.Count-ne 1){throw "Expected exactly one asclab-kv* Key Vault; found $($vault.Count)."};$kv=$vault[0];$kvr=Get-AzResource -ResourceGroupName $rg -ResourceType 'Microsoft.KeyVault/vaults' -Name $kv.VaultName -ExpandProperties -ErrorAction Stop;$kvpna=[string](P $kvr.Properties 'publicNetworkAccess');if($kvpna-notin @('Disabled','disabled')){throw "Key Vault '$($kv.VaultName)' public network access is '$kvpna', expected Disabled. Set it under Networking > Firewalls and virtual networks > Disable public access."};$name='Contoso Secure Workload Baseline';$policyId='2a1a9cdf-e04d-429a-8416-3bfb72a1b26f';$r=Invoke-AzRestMethod -Path "/subscriptions/$sub/providers/Microsoft.Security/securityStandards?api-version=2024-08-01" -Method GET -ErrorAction Stop;if([string]::IsNullOrWhiteSpace($r.Content)){throw 'Defender custom-standard API returned empty content.'};$items=@(($r.Content|ConvertFrom-Json).value|Where-Object{[string](P $_.properties 'displayName')-eq $name});if($items.Count-ne 1){throw "Defender returned $($items.Count) standards named '$name'."};$std=$items[0].properties;$ass=@(P $std 'assessments');$hit=$false;if($ass.Count-eq 1 -and (($ass[0]|ConvertTo-Json -Depth 12)-match [regex]::Escape($policyId))){$hit=$true}else{$psd=[string](P $std 'policySetDefinitionId');if([string]::IsNullOrWhiteSpace($psd)){throw "Custom standard '$name' exposes neither an assessment nor a policy set definition."};$pr=Invoke-AzRestMethod -Path "$psd`?api-version=2023-04-01" -Method GET -ErrorAction Stop;if([string]::IsNullOrWhiteSpace($pr.Content)){throw "Could not read the policy initiative behind custom standard '$name'."};$defs=@(($pr.Content|ConvertFrom-Json).properties.policyDefinitions);if($defs.Count-ne 1){throw "Custom standard '$name' must contain exactly one policy definition; found $($defs.Count)."};if([string]$defs[0].policyDefinitionId-notmatch [regex]::Escape($policyId)){throw "Custom standard '$name' must contain policy '$policyId'."};$hit=$true};if(-not $hit){throw "Custom standard '$name' does not contain policy '$policyId'."};$found=$true;Reply 'Succeeded' "Challenge 2 passed in '$rg': storage, SQL, Key Vault, and custom standard '$name' are correctly configured."}catch{$lastReason=$_.Exception.Message;Reply 'Failed' "Challenge 2 attempt $count of 3 failed: $lastReason";if($count-lt 3){Start-Sleep -Seconds 10}}}while($count-lt 3 -and -not $found)
if(-not $found){Reply 'Failed' "Challenge 2 failed after 3 attempts in '$rg'. Last actionable reason: $lastReason"}